// Processa a telemetria de cada lixeira: classifica o nível, grava no banco e decide se envia alerta.
const LIMITE_CHEIA = 85, LIMITE_ATENCAO = 60, LIMITE_REARME = 60;
const t = msg.payload || {};
const partes = msg.topic.split('/');
const id = t.id || partes[partes.length - 2];
const nivel = (t.nivel_pct === null || t.nivel_pct === undefined) ? null : Number(t.nivel_pct);

let status = 'sem_leitura';
if (nivel !== null && !isNaN(nivel)) {
    status = nivel >= LIMITE_CHEIA ? 'cheia' : (nivel >= LIMITE_ATENCAO ? 'atencao' : 'normal');
}
const cod = { normal: 0, atencao: 1, cheia: 2, sem_leitura: -1 };

const campos = { status: status, status_cod: cod[status], tampa_aberta: t.tampa === 'aberta' ? 1 : 0 };
if (nivel !== null && !isNaN(nivel)) campos.nivel_pct = nivel;
if (typeof t.distancia_cm === 'number') campos.distancia_cm = t.distancia_cm;
if (typeof t.rssi === 'number') campos.rssi = t.rssi;

// guarda o último nível conhecido para a regra de abertura da tampa
const niveis = flow.get('niveis') || {};
niveis[id] = nivel;
flow.set('niveis', niveis);

const ponto = [{ measurement: 'lixeira', tags: { lixeira: id }, fields: campos }];

// alerta uma única vez por ciclo de enchimento (histerese: rearma quando o nível cair abaixo de 60%)
const alertado = flow.get('alertado') || {};
let alerta = null;
if (nivel !== null && nivel >= LIMITE_CHEIA && !alertado[id]) {
    alertado[id] = true;
    alerta = { payload: {
        chatId: env.get('TELEGRAM_CHAT_ID'),
        type: 'message',
        content: '🚨 ' + id + ' está cheia (' + nivel.toFixed(0) + '%). Coleta necessária.'
    } };
} else if (nivel !== null && nivel < LIMITE_REARME && alertado[id]) {
    alertado[id] = false;
}
flow.set('alertado', alertado);

return [{ payload: ponto }, alerta];

// Regra de abertura da tampa: abre quando há presença, exceto se a lixeira estiver praticamente lotada (>= 95%).
const LIMITE_BLOQUEIO = 95;
const p = msg.payload || {};
const partes = msg.topic.split('/');
const id = p.id || partes[partes.length - 2];
const niveis = flow.get('niveis') || {};
const nivel = niveis[id];

const bloqueada = (typeof nivel === 'number') && nivel >= LIMITE_BLOQUEIO;
const comando = bloqueada ? null : { topic: 'upm/ioc/lixeira/' + id + '/cmd/tampa', payload: 'abrir', qos: 0, retain: false };
const registro = { payload: [{
    measurement: 'presenca',
    tags: { lixeira: id },
    fields: { detectada: 1, tampa_bloqueada: bloqueada ? 1 : 0 }
}] };
return [comando, registro];

// Avisa a equipe quando uma lixeira fica offline (Last Will do MQTT)
const partes = msg.topic.split('/');
const id = partes[partes.length - 2];
const estado = String(msg.payload).trim();
if (estado !== 'offline') return null;
return { payload: { chatId: env.get('TELEGRAM_CHAT_ID'), type: 'message', content: '⚠️ ' + id + ' ficou offline.' } };
